for j in ('en','uk'): w('si',j,'kupoprodajna-pogodba-avto','','',auto(j))
def moto(j):
  E=j=='en'; T=lambda a,b: a if E else b
  d=auto(j, True); L=d['landing']; p=d['pruvodce']['pole']
  p['znacka']['placeholder']=T('e.g. Yamaha MT-07','напр. Yamaha MT-07'); p['km']['placeholder']=T('e.g. 24300','напр. 24300')
  p['vin']['napoveda']=T('17 characters, field E of the registration certificate. On a motorcycle it is usually stamped into the frame at the steering head.','17 знаків, поле E свідоцтва про реєстрацію. На мотоциклі зазвичай вибитий на рамі біля рульової колонки.')
  p['napake_opis']['placeholder']=T('e.g. obrabljena veriga, praske na rezervoarju (worn chain, scratches on the tank)','напр. obrabljena veriga, praske na rezervoarju (зношений ланцюг, подряпини на баку)')
  d['pruvodce']['kontrola'].append(T('List the equipment and modifications (panniers, crash bars, exhaust) and check that modifications requiring type approval are entered in the registration certificate.','Укажіть обладнання й переробки (кофри, дуги безпеки, вихлоп) і перевірте, чи переробки, які потребують омологації, внесені до свідоцтва про реєстрацію.'))
  if not E: L['title']='Купівля-продаж мотоцикла Словенія {rok} – зразок PDF безкоштовно'
  L['perex']=T('For selling a used motorcycle, scooter or quad between private persons.','Для продажу вживаного мотоцикла, скутера чи квадроцикла між приватними особами.')
  L['obsah']=T([('Parties','Seller and buyer.'),('Subject','Vehicle, VIN, registration plate.'),('Condition','Mileage, defects, equipment (helmet, panniers).'),('Price','Amount and payment.'),('Handover and transfer','Time of handover, 15-day deadline.')],
               [('Сторони','Продавець і покупець.'),('Предмет','Транспортний засіб, VIN, номерний знак.'),('Стан','Пробіг, недоліки, обладнання (шолом, кофри).'),('Ціна','Сума й оплата.'),('Передача й переоформлення','Час передачі, строк 15 днів.')])
  L['online']=T(['Amount in words in Slovenian added automatically','VIN check','PDF and Word'],['Сума словами словенською – автоматично','Перевірка VIN','PDF і Word'])
  L['hodiSe']=[T('you are selling or buying a used motorcycle from a private person','ви продаєте або купуєте вживаний мотоцикл у приватної особи')]
  L['nehodiSe']=[T('you are buying from a dealer','ви купуєте в продавця-підприємця')]
  L['po']=T([('Handover','Vehicle handover report.'),('Transfer','Within 15 days at a registration organisation.')],[('Передача','Акт приймання-передачі транспортного засобу.'),('Переоформлення','Протягом 15 днів у реєстраційній організації.')])
  L['faq']=[T(('Is a scooter treated the same as a motorcycle?','Yes, for all registered vehicles the change of ownership must be reported within 15 days.'),('Чи для скутера діють ті самі правила, що й для мотоцикла?','Так, для всіх зареєстрованих транспортних засобів про зміну власника треба повідомити протягом 15 днів.'))]
  L['zakony']=T('The template is based on the Slovenian Obligations Code (Obligacijski zakonik) and information from the Ministry of Infrastructure.','Зразок ґрунтується на словенському Зобов’язальному кодексі (Obligacijski zakonik) та інформації Міністерства інфраструктури.')
  return d
for j in ('en','uk'): w('si',j,'kupoprodajna-pogodba-motor','','',moto(j))
